import express, { Request, Response, NextFunction } from 'express';
import crypto from 'crypto';
import session from 'express-session';

const app = express();

const MAX_INPUT_ROWS = 1000;
const MAX_INPUT_COLS = 1000;

interface ModelConfig {
  name: string;
  weights: string;
  threshold: number;
}

interface InferenceRequest {
  modelId: string;
  input: number[][];
  options?: { batchSize?: number; timeout?: number };
}

const models: Map<string, ModelConfig> = new Map();
const tokenStore: Map<string, { userId: string; expires: number }> = new Map();

app.use(express.json({ limit: '1mb' }));
app.use(session({
  secret: crypto.randomBytes(32).toString('hex'),
  resave: false,
  saveUninitialized: false,
  cookie: { httpOnly: true, secure: true, sameSite: 'strict' }
}));

function generateCsrfToken(sessionId: string): string {
  const token = crypto.randomBytes(32).toString('hex');
  tokenStore.set(token, { userId: sessionId, expires: Date.now() + 3600000 });
  return token;
}

function validateOrigin(req: Request): boolean {
  const origin = req.headers['origin'] || req.headers['referer'];
  const allowedOrigins = ['https://ml-platform.internal.corp'];
  if (!origin) return true; // Allow requests without origin (same-origin)
  return allowedOrigins.some(allowed => origin.startsWith(allowed));
}

async function verifyCsrfToken(req: Request): Promise<boolean> {
  const token = req.headers['x-csrf-token'] as string;
  const sessionId = req.session?.id;

  if (!token || !sessionId) return false;

  const stored = tokenStore.get(token);
  if (!stored) return false;

  if (stored.expires < Date.now()) {
    tokenStore.delete(token);
    return false;
  }

  // Timing-safe comparison for token ownership
  const a = Buffer.from(stored.userId, 'utf8');
  const b = Buffer.from(sessionId, 'utf8');
  if (a.length !== b.length) return false;
  return crypto.timingSafeEqual(a, b);
}

async function csrfProtection(req: Request, res: Response, next: NextFunction): Promise<void> {
  if (req.method === 'GET' || req.method === 'HEAD' || req.method === 'OPTIONS') {
    return next();
  }

  const originValid = validateOrigin(req);
  const tokenValid = await verifyCsrfToken(req);

  // Defense in depth: require BOTH valid origin AND valid token
  if (originValid && tokenValid) {
    return next();
  }

  res.status(403).json({ error: 'CSRF validation failed' });
}

app.use(csrfProtection);

app.get('/api/csrf-token', (req: Request, res: Response) => {
  const token = generateCsrfToken(req.session!.id);
  res.json({ token });
});

async function runInference(config: ModelConfig, input: number[][]): Promise<number[]> {
  // Simulate async ML inference
  await new Promise(resolve => setTimeout(resolve, 50));
  return input.map(row => 
    row.reduce((sum, val) => sum + val * config.threshold, 0)
  );
}

app.post('/api/models', async (req: Request, res: Response) => {
  const { name, weights, threshold } = req.body;
  if (!name || !weights || typeof threshold !== 'number') {
    return res.status(400).json({ error: 'Invalid model configuration' });
  }
  const modelId = crypto.randomUUID();
  models.set(modelId, { name, weights, threshold });
  res.status(201).json({ modelId });
});

app.post('/api/inference', async (req: Request, res: Response) => {
  const { modelId, input, options }: InferenceRequest = req.body;

  if (!modelId || !input || !Array.isArray(input)) {
    return res.status(400).json({ error: 'Invalid inference request' });
  }

  // Bound and validate input to prevent resource exhaustion / malformed data
  if (input.length === 0 || input.length > MAX_INPUT_ROWS) {
    return res.status(400).json({ error: 'Invalid input dimensions' });
  }
  for (const row of input) {
    if (!Array.isArray(row) || row.length === 0 || row.length > MAX_INPUT_COLS) {
      return res.status(400).json({ error: 'Invalid input dimensions' });
    }
    for (const val of row) {
      if (typeof val !== 'number' || !Number.isFinite(val)) {
        return res.status(400).json({ error: 'Input must contain finite numbers' });
      }
    }
  }

  const config = models.get(modelId);
  if (!config) {
    return res.status(404).json({ error: 'Model not found' });
  }

  const timeout = options?.timeout || 30000;
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeout);

  try {
    const results = await runInference(config, input);
    clearTimeout(timer);
    res.json({ predictions: results, model: config.name });
  } catch (err) {
    clearTimeout(timer);
    res.status(500).json({ error: 'Inference failed' });
  }
});

app.delete('/api/models/:id', async (req: Request, res: Response) => {
  const { id } = req.params;
  if (models.has(id)) {
    models.delete(id);
    res.status(204).send();
  } else {
    res.status(404).json({ error: 'Model not found' });
  }
});

app.listen(8443, () => console.log('ML Inference Server on :8443'));

export default app;
